-- sequence repair
-- 修复序列当前值，跳过已占用的硬编码 ID，避免后续手动录入时 ID 冲突
-- ============================================================
SELECT setval('qms.spc_process_id_seq', COALESCE((SELECT MAX(id) FROM qms.spc_process), 1));
SELECT setval('qms.spc_parameter_id_seq', COALESCE((SELECT MAX(id) FROM qms.spc_parameter), 1));
SELECT setval('qms.spc_subgroup_id_seq', COALESCE((SELECT MAX(id) FROM qms.spc_subgroup), 1));
SELECT setval('qms.spc_sample_id_seq', COALESCE((SELECT MAX(id) FROM qms.spc_sample), 1));
SELECT setval('qms.spc_control_limit_id_seq', COALESCE((SELECT MAX(id) FROM qms.spc_control_limit), 1));
SELECT setval('qms.spc_capability_id_seq', COALESCE((SELECT MAX(id) FROM qms.spc_capability), 1));
